result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "client.py", "content": """"In-memory sync client.

State:
  store    : id -> {"id", "body", "rev", "deleted"}   (mirror of server data)
  cursor   : last change-log seq seen
  pending  : id -> {"body", "deleted", "base_rev"}    (unpushed local intents)

Protocol:
  pull() : GET /changes?since=cursor and apply entries (server is truth).
  sync() : push pending ops; on a 409 the server copy is taken into the
           store ("server wins") and the local edit is re-applied on top of
           the new base_rev *only if* the intended outcome still differs
           from the server copy; then re-pushed. Repeats until quiescent.
"""

from typing import Dict


class Client:
    def __init__(self, http, name: str = ""):
        self.http = http          # any TestClient-compatible object
        self.name = name
        self.store: Dict[str, dict] = {}
        self.cursor = 0
        self.pending: Dict[str, dict] = {}

    # -- local mutations -----------------------------------------------------

    def _intent(self, nid, body, deleted):
        base = self.store[nid]["rev"] if nid in self.store else 0
        if nid in self.pending:
            # Keep the oldest base_rev we knew about; latest intent wins.
            self.pending[nid].update(body=body, deleted=deleted)
        else:
            self.pending[nid] = {"body": body, "deleted": deleted, "base_rev": base}

    def edit(self, nid: str, body: str):
        self._intent(nid, body, False)

    def delete(self, nid: str):
        self._intent(nid, None, True)

    def live_ids(self):
        return [i for i, r in self.store.items() if not r["deleted"]]

    # -- replication ---------------------------------------------------------

    def pull(self):
        data = self.http.get("/changes", params={"since": self.cursor}).json()
        for e in data["changes"]:
            rec = self.store.get(e["id"])
            if rec is None or e["rev"] >= rec["rev"]:
                self.store[e["id"]] = {
                    "id": e["id"],
                    "rev": e["rev"],
                    "body": e["body"],
                    "deleted": e["deleted"],
                }
        self.cursor = data["cursor"]

    def sync(self, max_rounds: int = 500):
        """Push all pending ops, resolving conflicts until nothing remains."""
        for _ in range(max_rounds):
            if not self.pending:
                return
            ops = [
                {
                    "id": nid,
                    "base_rev": p["base_rev"],
                    "body": p["body"],
                    "deleted": p["deleted"],
                }
                for nid, p in sorted(self.pending.items())
            ]
            for res in self.http.post("/push", json=ops).json():
                p = self.pending.pop(res["id"])
                if res["status"] == 409:
                    srv = res["server"]
                    if srv["rev"] > 0:
                        self.store[srv["id"]] = dict(srv)  # server wins
                    # Re-apply the local edit only if it still differs from
                    # what the server now holds; otherwise drop it.
                    differs = (
                        (p["deleted"] and not srv["deleted"])
                        or (not p["deleted"] and srv["body"] != p["body"])
                    )
                    if differs:
                        self.pending[srv["id"]] = {
                            "body": p["body"],
                            "deleted": p["deleted"],
                            "base_rev": srv["rev"],
                        }
                else:
                    self.store[res["id"]] = {
                        "id": res["id"],
                        "rev": res["rev"],
                        "body": p["body"],
                        "deleted": p["deleted"],
                    }
        raise RuntimeError(f"client {self.name!r}: sync did not converge")

    def fully_synced(self, server_cursor: int) -> bool:
        return not self.pending and self.cursor == server_cursor
"})
